#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD_CONST = 1000000007;
    long long p_int, k_int;
    cin >> p_int >> k_int;

    if (k_int == 0) {
        long long result = 1;
        long long base = p_int % MOD_CONST;
        long long exp = p_int - 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD_CONST;
            base = (base * base) % MOD_CONST;
            exp >>= 1;
        }
        cout << result << "\n";
    } else if (k_int == 1) {
        long long result = 1;
        long long base = p_int % MOD_CONST;
        long long exp = p_int;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD_CONST;
            base = (base * base) % MOD_CONST;
            exp >>= 1;
        }
        cout << result << "\n";
    } else {
        long long n_value = k_int;
        int order_counter = 1;
        while (n_value != 1) {
            n_value = (n_value * k_int) % p_int;
            order_counter++;
        }
        long long total_repeats = (p_int - 1) / order_counter;
        long long result = 1;
        long long base = p_int % MOD_CONST;
        long long exp = total_repeats;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD_CONST;
            base = (base * base) % MOD_CONST;
            exp >>= 1;
        }
        cout << result << "\n";
    }

    return 0;
}
